(function() {
    'use strict';

    class FMCGArenaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'FMCG Arena: Consumer Goods Competitive Operations';
            this.version = '1.1.0';

            this.SEGMENTS = {
                priceSensitive: { size: 2100, elasticity: -1.2, compAvgPrice: 0.75 },
                brandLoyal:     { size: 1400, elasticity: -0.6, compAvgPrice: 1.00 },
                premium:        { size: 800,  elasticity: -0.3, compAvgPrice: 1.38 }
            };

            this.EVENTS = [
                null,
                { key: 'event_round2', effect: 'competitor_launch' },
                { key: 'event_round3', effect: 'retail_consolidation' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 500,
                    marketSharePrice: 15,
                    marketShareBrand: 18,
                    marketSharePremium: 12,
                    brandEquity: 50,
                    inventory: 200,
                    totalProfit: 0,
                    cumulativeMarketing: 0,
                    cumulativeRD: 0,
                    profitHistory: [],
                    shareHistory: [],
                    brandHistory: [],
                    revenueHistory: [],
                    cashHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    priceEconomy: 0.72,
                    priceStandard: 0.98,
                    pricePremium: 1.35,
                    marketingBudget: 80,
                    tradePromoBudget: 60,
                    modernTradeAlloc: 55,
                    productionVolume: 700,
                    rdInvestment: 20
                };
            }
            this._updateEventBanner(state);
        }

        validateDecisions(decisions) {
            var pe = document.getElementById('priceEconomyInput');
            var ps = document.getElementById('priceStandardInput');
            var pp = document.getElementById('pricePremiumInput');
            var mk = document.getElementById('marketingInput');
            var tp = document.getElementById('tradePromoInput');
            var mt = document.getElementById('modernTradeInput');
            var pr = document.getElementById('productionInput');
            var rd = document.getElementById('rdInput');

            if (pe) decisions.priceEconomy = parseFloat(pe.value);
            if (ps) decisions.priceStandard = parseFloat(ps.value);
            if (pp) decisions.pricePremium = parseFloat(pp.value);
            if (mk) decisions.marketingBudget = parseFloat(mk.value);
            if (tp) decisions.tradePromoBudget = parseFloat(tp.value);
            if (mt) decisions.modernTradeAlloc = parseFloat(mt.value);
            if (pr) decisions.productionVolume = parseFloat(pr.value);
            if (rd) decisions.rdInvestment = parseFloat(rd.value);

            if (!decisions.priceEconomy || decisions.priceEconomy < 0.65 || decisions.priceEconomy > 0.82) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_price_economy'), 'warning'
                );
                return false;
            }
            if (!decisions.priceStandard || decisions.priceStandard < 0.90 || decisions.priceStandard > 1.10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_price_standard'), 'warning'
                );
                return false;
            }
            if (!decisions.pricePremium || decisions.pricePremium < 1.25 || decisions.pricePremium > 1.50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_price_premium'), 'warning'
                );
                return false;
            }
            if (decisions.marketingBudget < 0 || decisions.marketingBudget > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_marketing'), 'warning'
                );
                return false;
            }
            if (decisions.tradePromoBudget < 0 || decisions.tradePromoBudget > 150) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_trade_promo'), 'warning'
                );
                return false;
            }
            if (decisions.modernTradeAlloc < 20 || decisions.modernTradeAlloc > 80) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_modern_trade'), 'warning'
                );
                return false;
            }
            if (decisions.productionVolume < 400 || decisions.productionVolume > 1200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_production'), 'warning'
                );
                return false;
            }
            if (decisions.rdInvestment < 0 || decisions.rdInvestment > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_rd'), 'warning'
                );
                return false;
            }

            var totalSpend = decisions.marketingBudget + decisions.tradePromoBudget + decisions.rdInvestment;
            if (totalSpend > window.mySimulation.state.domainState.cash * 0.8) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_budget_exceed'), 'warning'
                );
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var brandMult = ds.brandEquity / 50;
            var marketingMult = 1 + (d.marketingBudget / 500) * 0.25;
            var tradePromoMult = 1 + (d.tradePromoBudget / 400) * 0.15;

            var rdQualityBoost = d.rdInvestment / 80;

            var eventMod = { priceSensitive: 1, brandLoyal: 1, premium: 1, modernTradeBonus: 0 };
            if (period === 2) {
                eventMod.premium = 0.88;
                eventMod.brandLoyal = 0.95;
            }
            if (period === 3) {
                eventMod.modernTradeBonus = 0.10;
            }

            var prices = {
                priceSensitive: d.priceEconomy,
                brandLoyal: d.priceStandard,
                premium: d.pricePremium
            };

            var shares = {
                priceSensitive: ds.marketSharePrice,
                brandLoyal: ds.marketShareBrand,
                premium: ds.marketSharePremium
            };

            var segKeys = ['priceSensitive', 'brandLoyal', 'premium'];
            var segSales = {};
            var segRevenue = {};
            var totalSales = 0;
            var totalRevenue = 0;

            for (var i = 0; i < segKeys.length; i++) {
                var seg = segKeys[i];
                var info = this.SEGMENTS[seg];
                var priceRatio = info.compAvgPrice / prices[seg];
                var priceElastMult = Math.pow(priceRatio, Math.abs(info.elasticity));

                var qualityMult = 1 + rdQualityBoost * (seg === 'premium' ? 0.15 : (seg === 'brandLoyal' ? 0.08 : 0.03));

                var channelMult = 1;
                if (seg === 'premium' || seg === 'brandLoyal') {
                    channelMult = 1 + (d.modernTradeAlloc - 50) / 200;
                } else {
                    channelMult = 1 + (50 - d.modernTradeAlloc) / 300;
                }

                var evMod = eventMod[seg] || 1;

                var adjustedShare = shares[seg] * priceElastMult * marketingMult * brandMult * qualityMult * tradePromoMult * channelMult * evMod;
                adjustedShare = Math.max(2, Math.min(40, adjustedShare));

                var demand = info.size * (adjustedShare / 100);
                segSales[seg] = demand;
                segRevenue[seg] = demand * prices[seg];
                totalSales += demand;
                totalRevenue += demand * prices[seg];

                shares[seg] = Math.round(adjustedShare * 10) / 10;
            }

            var available = ds.inventory + d.productionVolume;
            var actualSalesRatio = 1;
            if (totalSales > available) {
                actualSalesRatio = available / totalSales;
                totalSales = available;
                totalRevenue = totalRevenue * actualSalesRatio;
            }

            var variableCost = 0.35;
            var fixedManufacturing = 100;
            var scaleEffect = 1 - (d.productionVolume - 400) / 8000;
            scaleEffect = Math.max(0.85, Math.min(1.0, scaleEffect));
            var effectiveVarCost = variableCost * scaleEffect;
            var cogs = totalSales * effectiveVarCost + fixedManufacturing;

            var grossProfit = totalRevenue - cogs;
            var grossMarginPct = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;

            var salesForceCost = 35 + (d.modernTradeAlloc / 100) * 20 + ((100 - d.modernTradeAlloc) / 100) * 25;
            var logisticsCost = totalSales * 0.02 + (100 - d.modernTradeAlloc) * 0.3;

            var totalOpex = d.marketingBudget + d.tradePromoBudget + d.rdInvestment + salesForceCost + logisticsCost;
            var operatingProfit = grossProfit - totalOpex;

            var endingInventory = available - totalSales;
            var spoilageRate = 0.02 + Math.max(0, endingInventory - 100) * 0.0003;
            var spoilage = endingInventory * spoilageRate;
            endingInventory = Math.max(0, endingInventory - spoilage);

            var holdingCost = endingInventory * effectiveVarCost * 0.02;
            operatingProfit -= holdingCost;
            operatingProfit -= spoilage * effectiveVarCost;

            var incrementalVolumeFromPromo = totalSales * (tradePromoMult - 1);
            var incrementalMargin = incrementalVolumeFromPromo * (totalRevenue / totalSales - effectiveVarCost);
            var promoROI = d.tradePromoBudget > 0 ? ((incrementalMargin - d.tradePromoBudget) / d.tradePromoBudget) * 100 : 0;

            var brandDelta = (d.marketingBudget / 50) * 2 + (d.rdInvestment / 30) * 1.5 - (d.tradePromoBudget / 100) * 1 + (rdQualityBoost * 3);
            if (period === 2 && d.rdInvestment >= 40) brandDelta += 5;
            var newBrandEquity = Math.max(10, Math.min(100, ds.brandEquity + brandDelta));

            var totalShare = (shares.priceSensitive * 2100 + shares.brandLoyal * 1400 + shares.premium * 800) / 4300;

            var baselineShare = (ds.marketSharePrice * 2100 + ds.marketShareBrand * 1400 + ds.marketSharePremium * 800) / 4300;
            var shareDelta = totalShare - baselineShare;

            var spoilagePct = (available > 0) ? (spoilage / available) * 100 : 0;
            var inventoryEfficiency = 100 - spoilagePct * 5;
            inventoryEfficiency = Math.max(0, Math.min(100, inventoryEfficiency));

            var cogsRatio = totalRevenue > 0 ? (cogs / totalRevenue) * 100 : 100;
            var productionEfficiency = Math.max(0, 100 - cogsRatio);

            var mpi = 0;
            mpi += Math.min(25, Math.max(0, operatingProfit / 4)) * 0.25;
            mpi += Math.min(25, totalShare * 0.625) * 0.20;
            mpi += Math.min(25, newBrandEquity * 0.25) * 0.20;
            mpi += Math.min(25, Math.max(0, operatingProfit / 3)) * 0.15;
            mpi += Math.min(25, inventoryEfficiency * 0.25) * 0.10;
            mpi += Math.min(25, productionEfficiency * 0.25) * 0.10;

            if (shareDelta < -3) mpi -= 10;
            if (spoilagePct > 5) mpi -= 5;
            if (actualSalesRatio < 1) mpi -= 10;

            mpi = Math.round(Math.max(0, mpi) * 10) / 10;

            ds.cash += operatingProfit;
            ds.totalProfit += operatingProfit;
            ds.inventory = Math.round(endingInventory);
            ds.marketSharePrice = shares.priceSensitive;
            ds.marketShareBrand = shares.brandLoyal;
            ds.marketSharePremium = shares.premium;
            ds.brandEquity = Math.round(newBrandEquity * 10) / 10;
            ds.cumulativeMarketing += d.marketingBudget;
            ds.cumulativeRD += d.rdInvestment;

            ds.profitHistory.push(Math.round(operatingProfit * 10) / 10);
            ds.shareHistory.push(Math.round(totalShare * 10) / 10);
            ds.brandHistory.push(Math.round(newBrandEquity * 10) / 10);
            ds.revenueHistory.push(Math.round(totalRevenue * 10) / 10);
            ds.cashHistory.push(Math.round(ds.cash * 10) / 10);

            var resultsPanel = document.getElementById('resultsPanel');
            if (resultsPanel) resultsPanel.style.display = 'block';

            var self = this;
            setTimeout(function() {
                self._updateEventBanner({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                revenue: Math.round(totalRevenue * 10) / 10,
                cogs: Math.round(cogs * 10) / 10,
                grossMargin: Math.round(grossMarginPct * 10) / 10,
                totalSales: Math.round(totalSales),
                operatingProfit: Math.round(operatingProfit * 10) / 10,
                totalShare: Math.round(totalShare * 10) / 10,
                brandEquity: Math.round(newBrandEquity * 10) / 10,
                spoilage: Math.round(spoilage),
                promoROI: Math.round(promoROI * 10) / 10,
                mpi: mpi,
                inventory: ds.inventory,
                cash: Math.round(ds.cash * 10) / 10,
                sharePriceSeg: shares.priceSensitive,
                shareBrandSeg: shares.brandLoyal,
                sharePremSeg: shares.premium
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return Math.round(v).toLocaleString() + ' M'; });
            uiManager.bind('shareDisplay', 'results.totalShare',
                function(v) { return v + '%'; });
            uiManager.bind('brandDisplay', 'domainState.brandEquity',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('inventoryDisplay', 'domainState.inventory',
                function(v) { return Math.round(v).toLocaleString() + ' M'; });
            uiManager.bind('profitDisplay', 'results.operatingProfit',
                function(v) { return (v >= 0 ? '' : '-') + Math.abs(Math.round(v)).toLocaleString() + ' M'; });
            uiManager.bind('mpiDisplay', 'results.mpi',
                function(v) { return v.toFixed(1); });
            uiManager.bind('revenueDisplay', 'results.revenue',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('cogsDisplay', 'results.cogs',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('grossMarginDisplay', 'results.grossMargin',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('totalSalesDisplay', 'results.totalSales',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('spoilageDisplay', 'results.spoilage',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('promoRoiDisplay', 'results.promoROI',
                function(v) { return v.toFixed(1) + '%'; });
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Operating Profit (M AP)',
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.15)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2,
                            pointRadius: 6,
                            pointBackgroundColor: '#27ae60'
                        }, {
                            label: 'Revenue (M AP)',
                            data: [],
                            borderColor: '#2e86c1',
                            backgroundColor: 'rgba(46,134,193,0.08)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.2,
                            pointRadius: 5,
                            pointBackgroundColor: '#2e86c1',
                            yAxisID: 'y'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Financial Performance' }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                },
                shareChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Market Share (%)',
                            data: [],
                            backgroundColor: 'rgba(46,134,193,0.6)',
                            borderColor: '#2e86c1',
                            borderWidth: 2,
                            borderRadius: 8
                        }, {
                            label: 'Brand Equity',
                            data: [],
                            backgroundColor: 'rgba(142,68,173,0.5)',
                            borderColor: '#8e44ad',
                            borderWidth: 2,
                            borderRadius: 8
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Market Position and Brand Strength' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.profitHistory.map(function(_, i) { return 'Y' + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.profitHistory },
                        { data: state.domainState.revenueHistory }
                    ]
                },
                shareChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.shareHistory },
                        { data: state.domainState.brandHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.operatingProfit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastMPI = history[history.length - 1].results ? history[history.length - 1].results.mpi || 0 : 0;
            var lastShare = history[history.length - 1].results ? history[history.length - 1].results.totalShare || 0 : 0;
            var lastBrand = history[history.length - 1].results ? history[history.length - 1].results.brandEquity || 0 : 0;

            var performance = 'Needs Improvement';
            if (lastMPI > 8 && totalProfit > 100) performance = 'Market Leader';
            else if (lastMPI > 5 && totalProfit > 50) performance = 'Strong Performer';
            else if (lastMPI > 3 && totalProfit > 0) performance = 'Developing';

            var insights = [];
            if (avgProfit > 40) {
                insights.push('Excellent profit generation. Strong operational efficiency combined with effective pricing.');
            } else if (avgProfit > 0) {
                insights.push('Positive profitability achieved. Focus on brand investment and channel optimization for growth.');
            } else {
                insights.push('Profitability was negative. Excessive discounting or insufficient volume may be the cause.');
            }

            if (lastBrand > 70) {
                insights.push('Outstanding brand equity. This positions the company for premium pricing power.');
            } else if (lastBrand < 40) {
                insights.push('Brand equity declined. Heavy trade promotion without brand investment erodes long-term value.');
            }

            if (lastShare > 20) {
                insights.push('Strong market share performance. Volume advantages should improve cost structure.');
            } else if (lastShare < 12) {
                insights.push('Market share loss indicates competitive weakness. Review pricing and channel strategy.');
            }

            return {
                totalProfit: Math.round(totalProfit),
                avgProfit: Math.round(avgProfit),
                finalMPI: lastMPI,
                finalShare: lastShare,
                finalBrand: lastBrand,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.operatingProfit < 0) return window.mySimulation.t('hint_loss');
            if (results.promoROI < -20) return window.mySimulation.t('hint_promo_negative');
            if (results.spoilage > 30) return window.mySimulation.t('hint_spoilage');
            if (results.totalShare < 10) return window.mySimulation.t('hint_low_share');
            if (results.brandEquity > 70 && results.operatingProfit > 30) return window.mySimulation.t('hint_strong');
            if (state.currentPeriod === 1 && results.operatingProfit > 0) return window.mySimulation.t('hint_good_start');
            return null;
        }

